725	                d.rev,
726	                work.display()
727	            );
728	        } else {
729	            info!(
730	                "commit: [dry-run] the work commit {work_chid}, in {}:\n{work_desc}",
731	                work.display()
732	            );
733	        }
734	        if agent_now {
735	            info!(
736	                "commit: [dry-run] the agent commit {agent_chid}, in {}:\n{agent_desc}",
737	                agent.display()
738	            );
739	        } else {
740	            info!(
741	                "commit: [dry-run] the agent @ {agent_chid} is left for push to commit as the partner"
742	            );
743	        }
