774	            );
775	            ctx.session(work)?.describe(&d.rev, &work_desc)
776	        }
777	    };
778	    if let Err(e) = made {
779	        snapshots.restore(pair, "commit", e.as_ref());
780	        return Err(e);
781	    }
782	    if !agent_now {
