784	        info!(
785	            "commit: the work half is made, its trailer naming the agent @ {agent_chid}, which \
786	             push commits as the partner. Review it with `vc-x1 show -s work @- -R {}`",
787	            work.display()
788	        );
789	        return push_after(
790	            ctx,
791	            work,
792	            Publish::Pair,
793	            plan.advance.as_deref(),
794	            params,
795	            false,
796	            land.as_ref(),
797	        );
798	    }
799	    info!("commit agent: {} -> @- {agent_chid}", agent.display());
800	    if let Err(e) = ctx.session(agent)?.commit(&agent_desc) {
801	        snapshots.restore(pair, "commit", e.as_ref());
802	        return Err(e);
803	    }
804	    finish_bookmarks(ctx, work, params, &plan)?;
805	    info!(
806	        "commit: the pair is made, review it with `vc-x1 show -s both {work_at} -R {}`",
807	        work.display()
