60	/// Problems found with an ochid trailer, with details for reporting.
61	#[derive(Debug)]
62	pub struct OchidIssues {
63	    /// None if prefix is correct, Some((actual_prefix, expected_prefix)) if wrong.
64	    pub wrong_prefix: Option<(String, String)>,
65	    /// None if length is correct, Some((actual_len, expected_len)) if wrong.
66	    pub wrong_length: Option<(usize, usize)>,
67	    /// true if the bare ID does not resolve in the other repo.
68	    pub not_found: bool,
69	    /// The bare ID extracted from the ochid value.
70	    pub bare_id: String,
71	}
72	
73	impl OchidIssues {
74	    pub fn any(&self) -> bool {
75	        self.wrong_prefix.is_some() || self.wrong_length.is_some() || self.not_found
76	    }
77	
78	    pub fn summary(&self) -> String {
79	        let mut parts = Vec::new();
80	        if let Some((ref actual, ref expected)) = self.wrong_prefix {
81	            parts.push(format!("prefix: {actual} (want {expected})"));
82	        }
83	        if let Some((actual, expected)) = self.wrong_length {
84	            parts.push(format!("len: {actual} (want {expected})"));
85	        }
86	        if self.not_found {
87	            parts.push(format!("not found: {}", self.bare_id));
88	        }
89	        parts.join(", ")
90	    }
91	}
