130	/// Result of searching the other repo for a matching commit by title.
131	#[derive(Debug)]
132	pub enum TitleMatch {
133	    /// No title to search for (empty description).
134	    NoTitle,
135	    /// Exactly one commit with the same title: unambiguous match.
136	    One(String),
137	    /// Multiple commits share the same title: ambiguous.
138	    Ambiguous(usize),
139	    /// No commit in the other repo has the same title.
140	    None,
141	}
142	
143	/// Find matching commits in the other repo by title (exact match).
144	pub fn find_matching_commit(
145	    commit: &jj_lib::commit::Commit,
146	    other_workspace: &Workspace,
147	    other_repo: &Arc<ReadonlyRepo>,
148	) -> Result<TitleMatch, Box<dyn std::error::Error>> {
149	    let title = commit.description().lines().next().unwrap_or(""); // OK: obvious
150	    if title.is_empty() {
151	        return Ok(TitleMatch::NoTitle);
152	    }
153	
154	    let all_ids = common::resolve_revset(other_workspace, other_repo, "all()")?;
155	    let root_id = other_repo.store().root_commit_id().clone();
156	
157	    let mut matches = Vec::new();
158	    for cid in &all_ids {
159	        if *cid == root_id {
160	            continue;
161	        }
162	        let other_commit = other_repo.store().get_commit(cid)?;
163	        let other_title = other_commit.description().lines().next().unwrap_or(""); // OK: obvious
164	        if other_title == title {
165	            let full_hex =
166	                jj_lib::hex_util::encode_reverse_hex(other_commit.change_id().as_bytes());
167	            matches.push(full_hex);
168	        }
169	    }
170	
171	    match matches.len() {
172	        0 => Ok(TitleMatch::None),
173	        1 => {
174	            #[allow(clippy::unwrap_used)]
175	            // OK: `1 =>` arm guarantees matches.len() == 1
176	            Ok(TitleMatch::One(matches.into_iter().next().unwrap()))
177	        }
178	        n => Ok(TitleMatch::Ambiguous(n)),
179	    }
180	}
