182	/// Resolve a short change ID to its full hex via the other repo.
183	pub fn resolve_full_change_id(
184	    bare_id: &str,
185	    other_workspace: &Workspace,
186	    other_repo: &Arc<ReadonlyRepo>,
187	) -> Result<Option<String>, Box<dyn std::error::Error>> {
188	    if let Ok(commit_ids) = common::resolve_revset(other_workspace, other_repo, bare_id)
189	        && let Some(cid) = commit_ids.first()
190	    {
191	        let other_commit = other_repo.store().get_commit(cid)?;
192	        let full_hex = jj_lib::hex_util::encode_reverse_hex(other_commit.change_id().as_bytes());
193	        Ok(Some(full_hex))
194	    } else {
195	        Ok(None)
196	    }
197	}
