199	/// Extract the bare change ID from an ochid value (strip path prefix).
200	pub fn extract_bare_id(ochid_value: &str) -> &str {
201	    if let Some(pos) = ochid_value.rfind('/') {
202	        &ochid_value[pos + 1..]
203	    } else {
204	        ochid_value
205	    }
206	}
