208	/// Fix the ochid trailer in a commit description.
209	///
210	/// If `resolved_id` is provided, it replaces the bare changeID entirely
211	/// (used when the existing ID is too short to extend by truncation alone).
212	pub fn fix_ochid_in_description(
213	    desc: &str,
214	    other_prefix: &str,
215	    id_len: usize,
216	    new_title: Option<&str>,
217	    resolved_id: Option<&str>,
218	) -> String {
219	    let mut lines: Vec<String> = desc.lines().map(|l| l.to_string()).collect();
220	
221	    // Fix title if requested
222	    if let Some(title) = new_title
223	        && !lines.is_empty()
224	    {
225	        lines[0] = title.to_string();
226	    }
227	
228	    // Fix ochid trailer
229	    for line in &mut lines {
230	        let trimmed = line.trim();
231	        if let Some(value) = trimmed.strip_prefix("ochid:") {
232	            let value = value.trim();
233	            let id = if let Some(rid) = resolved_id {
234	                &rid[..rid.len().min(id_len)]
235	            } else {
236	                let bare_id = extract_bare_id(value);
237	                &bare_id[..bare_id.len().min(id_len)]
238	            };
239	            *line = format!("ochid: {other_prefix}{id}");
240	        }
241	    }
242	
243	    // Preserve trailing newline if original had one
244	    let mut result = lines.join("\n");
245	    if desc.ends_with('\n') {
246	        result.push('\n');
247	    }
248	    result
249	}
250	
251	/// Append an ochid trailer to a commit description.
252	pub fn append_ochid_trailer(
253	    desc: &str,
254	    other_prefix: &str,
255	    change_id: &str,
256	    id_len: usize,
257	) -> String {
258	    let short_id = &change_id[..change_id.len().min(id_len)];
259	    let trailer = format!("ochid: {other_prefix}{short_id}");
260	
261	    let mut result = desc.trim_end().to_string();
262	    // Add blank line before trailer if body exists, otherwise just newline
263	    if result.lines().count() > 1 {
264	        result.push('\n');
265	    } else {
266	        result.push_str("\n\n");
267	    }
268	    result.push_str(&trailer);
269	    result.push('\n');
270	    result
271	}
272	
273	/// Extract the values of column-0 `ochid:` trailer lines from a
274	/// commit description, in order of appearance: the crate's one
275	/// string-level ochid parser.
276	///
277	/// - Column-0 only: an indented `ochid:` is quoted prose, not a
278	///   trailer (git trailers sit at column 0).
279	/// - Values are whitespace-trimmed. Blank values are skipped.
280	pub fn extract_ochids(desc: &str) -> Vec<String> {
281	    desc.lines()
282	        .filter_map(|line| line.strip_prefix("ochid:"))
283	        .map(|value| value.trim().to_string())
284	        .filter(|value| !value.is_empty())
285	        .collect()
286	}
287	
288	/// Extract "the" ochid value from a description string (without
289	/// needing a Commit): the *last* `ochid:` trailer, since trailers
290	/// sit at the end of the body. On a multi-ochid commit the
291	/// single-value view is the final trailer.
292	pub fn extract_ochid_from_desc(desc: &str) -> Option<String> {
293	    extract_ochids(desc).pop()
294	}
