52	/// Resolve `commit`'s partners on the other side, `there`.
53	///
54	/// - With trailers, each names a change id that must resolve there,
55	///   and a trailer that resolves to nothing is an error, since a
56	///   dangling trailer is a broken link and not a missing one.
57	/// - Without, every commit there within `tolerance_secs` of the
58	///   commit's committer time is a candidate.
59	pub fn partners(
60	    commit: &Commit,
61	    there: (&Workspace, &Arc<ReadonlyRepo>),
62	    tolerance_secs: i64,
63	) -> Result<Partner, Box<dyn std::error::Error>> {
64	    let (workspace, repo) = there;
65	    let trailers = extract_ochids(commit.description());
66	    if trailers.is_empty() {
67	        return candidates(commit, there, tolerance_secs);
68	    }
69	    let mut linked = Vec::new();
