73	            format!(
74	                "ochid: {trailer} names no commit on the other side, in '{}'",
75	                workspace.workspace_root().display()
76	            )
77	        };
78	        let ids = match common::resolve_revset(workspace, repo, bare) {
79	            Ok(ids) if ids.is_empty() => return Err(dangling().into()),
80	            Ok(ids) => ids,
81	            Err(e) if crate::jj::is_no_such_revision(e.as_ref()) => return Err(dangling().into()),
82	            Err(e) => return Err(e),
83	        };
84	        for id in &ids {
85	            linked.push(repo.store().get_commit(id)?);
86	        }
87	    }
88	    Ok(Partner::Linked(linked))
89	}
