130	/// The URL git remote `name` fetches from in the colocated repo at
131	/// `repo`, or `None` when there is no such remote. Read with gix from
132	/// the git side, the half of a colocated repo that holds remotes.
133	pub fn remote_url(repo: &Path, name: &str) -> Result<Option<String>> {
134	    let git = gix::open(repo)?;
135	    let Ok(remote) = git.find_remote(name) else {
136	        return Ok(None);
137	    };
138	    Ok(remote
139	        .url(gix::remote::Direction::Fetch)
140	        .map(|u| u.to_bstring().to_string()))
141	}
