125	/// Derive the project name from a URL or `owner/name` shorthand.
126	///
127	/// - Strips trailing `.git`.
128	/// - Returns the last segment after the rightmost `/` or `:`.
129	/// - Errors when the resulting name would be empty.
130	pub fn derive_name(url: &str) -> Result<String, Box<dyn std::error::Error>> {
131	    let stem = url.strip_suffix(".git").unwrap_or(url); // OK: .git suffix is optional
132	    // OK: rsplit always yields at least one element
133	    let last = stem.rsplit(['/', ':']).next().unwrap_or("");
134	    if last.is_empty() {
135	        return Err(format!("cannot derive project name from '{url}'").into());
136	    }
137	    Ok(last.to_string())
138	}
