140	/// Derive the agent-repo's remote name from the agent dir, for a
141	/// work-side config that records no `[remote] agent-repo`.
142	///
143	/// The dir is the config's `repos.agent`, and its last component
144	/// names the repo:
145	///
146	/// - Dot-led (`.claude`, `.agent-session`): a suffix, appended to the
147	///   work repo's name (`repo` + `.claude` -> `repo.claude`). This is
148	///   the shape init writes, the dir and the suffix one value.
149	/// - Otherwise (`../repo-agent`): the whole name.
150	/// - No last component (`..`, `/`), or one that is not UTF-8: an
151	///   error, since nothing names the repo.
152	pub fn derive_agent_repo(
153	    work_url: &str,
154	    agent_dir: &Path,
155	) -> Result<String, Box<dyn std::error::Error>> {
156	    let Some(last) = agent_dir.file_name().and_then(|s| s.to_str()) else {
157	        return Err(format!(
158	            "cannot derive the agent-repo's name from the agent dir '{}': \
159	             record it as [remote] agent-repo",
160	            agent_dir.display()
161	        )
162	        .into());
163	    };
164	    if last.starts_with('.') {
165	        Ok(format!("{}{last}", derive_name(work_url)?))
166	    } else {
167	        Ok(last.to_string())
168	    }
169	}
170	
171	/// Derive the agent-repo URL from the work-side URL and the
172	/// agent-repo's remote name.
173	///
174	/// The owner and the host come from the work URL, so only the last
175	/// segment is replaced and a fork under a different owner resolves
176	/// to that owner's agent-repo.
177	///
178	/// - `agent_repo` is `[remote] agent-repo`, the name the work-side
179	///   config declares, or [`derive_agent_repo`]'s name when it
180	///   declares none.
181	pub fn agent_url(work_url: &str, agent_repo: &str) -> String {
182	    let (stem, git) = match work_url.strip_suffix(".git") {
183	        Some(stem) => (stem, ".git"),
184	        None => (work_url, ""),
185	    };
186	    let cut = stem.rfind(['/', ':']).map_or(0, |i| i + 1);
187	    format!("{}{agent_repo}{git}", &stem[..cut])
188	}
