/// Whether `--opening`'s bookmark is pushed: not when `--skip` leaves
/// the push out, else the flag given, else the repo's `[commit] push`,
/// the same choice the commit's own push makes, so a cycle kept local
/// publishes nothing at its opening.
fn opening_pushes(
    repo: &Path,
    params: &CommitParams,
    o: &Opening,
) -> Result<bool, Box<dyn std::error::Error>> {
    if !o.pushes() {
        return Ok(false);
    }
    match params.push {
        Some(push) => Ok(push),
        None => configured_push(repo),
