/// `--local` and its alias keep the opening's bookmark off the remote
/// with no `--skip`, as `[commit] push = false` does, and `--push`
/// overrides the key. A `@-` on no remote is no refusal then, since
/// nothing is published.
#[test]
fn an_opening_kept_local_pushes_no_bookmark() {
    let open = |tag: &str, flag: Option<&str>, key_false: bool| {
        let fx = Fixture::new(&format!("commit-opening-local-{tag}"));
        if key_false {
            let config = fx.work.join(".vc-config.md");
            let text = fs::read_to_string(&config).expect("read");
            let text = format!("{text}\n```toml\n[commit]\npush = false\n```\n");
            fs::write(&config, text).expect("write");
        }
        fs::write(fx.work.join("opening.txt"), "opening\n").expect("write");
        let mut argv = vec![
            "vc-x1",
            "commit",
            "-s",
            "w",
            "--opening",
            "feat-x",
            "--title",
            "feat: x",
            "--body",
            "why",
        ];
        argv.extend(flag);
        let mut a = parse(&argv).expect("parses");
        a.repo = Some(fx.work.clone());
        let params = CommitParams::try_from(&a).expect("params");
        commit(&mut test_ctx(), &params).expect("the opening is made");
        bookmark_state(&fx.work, "feat-x")
    };
    for (tag, flag, key_false) in [
        ("flag", Some("--local"), false),
        ("alias", Some("--no-push"), false),
        ("key", None, true),
    ] {
        let (local, remote) = open(tag, flag, key_false);
        assert!(local.is_some(), "{tag}: the bookmark is made");
        assert_eq!(remote, None, "{tag}: nothing is pushed");
    }
    let (_, remote) = open("push", Some("--push"), true);
    assert!(remote.is_some(), "--push overrides the key");
}

