41	/// A `--body` value: the text as given, or the file an `@PATH`
42	/// names, since a body in commit-body form has markers and blank
43	/// lines a shell quote mangles. `who` prefixes the error.
44	pub fn read_body(body: &str, who: &str) -> Result<String, String> {
45	    match body.strip_prefix('@') {
46	        Some(path) if !path.is_empty() => std::fs::read_to_string(path)
47	            .map_err(|e| format!("{who}: --body @{path}: cannot read the file: {e}")),
48	        _ => Ok(body.to_string()),
