654	/// Make the pair: both change ids read from the working copies
655	/// first, then the work commit with the agent's id in its trailer
656	/// and, with `agent_now`, the agent commit with the work's id in
657	/// its own. Without it the agent `@` is left for push to commit as
658	/// the partner, its id already in the work commit's trailer.
659	fn commit_pair(
660	    ctx: &mut Context,
661	    pair: &Pair,
662	    agent_now: bool,
663	    params: &CommitParams,
664	) -> Result<(), Box<dyn std::error::Error>> {
665	    let (work, agent) = (pair.work.as_path(), pair.agent.as_path());
666	    let closing = plan_closing(work, params)?;
667	    let tip = closing_tip(closing.as_ref()).to_string();
668	    let closing_bm = closing_bookmark(work, params, &tip)?;
669	    let land = plan_land(work, params, &tip, closing_bm.as_deref())?;
670	    let record = match &closing {
671	        Some(_) => RecordMove::plan(work)?,
672	        None => None,
673	    };
674	    if let Some(ClosingPlan::Finalize { title, body }) = &closing {
675	        let body = finalized_body(
676	            work,
677	            body.as_deref(),
678	            record.as_ref().map(|r| r.name.as_str()),
679	        )?;
680	        if let Some(r) = &record {
681	            r.write(params.dry_run)?;
682	        }
683	        finalize(ctx, work, Some(pair), title, Some(&body), params.dry_run)?;
684	        return push_after(
685	            ctx,
686	            work,
687	            Publish::Pair,
688	            closing_bm.as_deref(),
689	            params,
690	            params.dry_run,
691	            land.as_ref(),
692	        );
693	    }
694	    let draft = plan_draft(work, params)?;
695	    match &draft {
696	        None => preflight(work, "work", closing.is_none())?,
697	        Some(_) => crate::pair::refuse_conflicts(work, "commit", "work")?,
698	    }
699	    preflight(agent, "agent", false)?;
700	    warn_unflagged_closing(params);
701	    let (text, merge) = description(params, closing)?;
702	    let plan = plan_bookmarks(work, params, draft.as_ref(), closing_bm.as_deref())?;
