147	/// Rewrite the placeholder `ochid: /none` trailers on both sides
148	/// of a dual-repo workspace so each initial commit points at its
149	/// counterpart's chid (init step 6).
150	///
151	/// Both sides must already have an initial commit shaped by
152	/// `OchidStrategy::Placeholder`. After the rewrite, each commit's
153	/// ochid trailer is a workspace-root-relative path: the work side
154	/// points at `/.claude/<bot_chid>` and the bot side points at
155	/// `/<work_chid>`.
156	///
157	/// Parameters:
158	/// - `work_dir`: work repo on disk, receiving `/.claude/<chid>`.
159	/// - `work_title`: the work commit's title, kept as it is: an adopted
160	///   repo's commit is not its first.
161	/// - `work_chid`: work-side initial-commit chid, embedded into
162	///   the bot-side trailer.
163	/// - `bot_dir`: bot repo on disk, receiving `/<chid>`.
164	/// - `bot_chid`: bot-side initial-commit chid, embedded
165	///   into the work-side trailer.
166	pub fn cross_ref_ochids(
167	    work_dir: &Path,
168	    work_title: &str,
169	    work_chid: &str,
170	    bot_dir: &Path,
171	    bot_chid: &str,
172	) -> Result<(), Box<dyn std::error::Error>> {
173	    debug!("set ochid cross-references");
174	    // Each side is named by its canonical label, never by its
175	    // directory: `/.claude` is the agent side's whatever the
176	    // directory is called, the label `push` writes and `validate-desc`
177	    // checks.
178	    let work_desc = format!("{work_title}\n\nochid: {OCHID_BOT_LABEL}/{bot_chid}");
179	    let bot_desc = format!("{INITIAL_TITLE}\n\nochid: {OCHID_WORK_LABEL}{work_chid}");
180	
181	    debug!("work side: rewrite initial commit's ochid to point at bot chid");
182	    jj::describe(work_dir, "@-", &work_desc)?;
183	    debug!("bot side: rewrite initial commit's ochid to point at work chid");
184	    jj::describe(bot_dir, "@-", &bot_desc)?;
185	
186	    debug!("surface post-describe commit ids for the debug log");
187	    // Colocated, so the jj commit id is the git hash.
188	    let hash = jj::cid_of(work_dir, "@-")?;
189	    debug!("work repo: chid={work_chid} hash={hash}");
190	    let hash = jj::cid_of(bot_dir, "@-")?;
191	    debug!(".claude:   chid={bot_chid} hash={hash}");
192	    Ok(())
193	}
