/// A description without its `ochid:` lines, trimmed, the text a
/// partner commit shares.
fn without_trailers(desc: &str) -> String {
    desc.lines()
        .filter(|l| !l.starts_with("ochid:"))
        .collect::<Vec<_>>()
        .join("\n")
        .trim_end()
        .to_string()
}

