1	//! Land: make a finished cycle permanent on its trunk. The trunk is
2	//! fast-forwarded to the cycle's last commit and pushed with the agent
3	//! half as its partner, and the cycle's bookmark is deleted locally and
4	//! on `origin`, every check made before anything moves.
5	//!
6	//! - [`plan`] refuses before anything is made: the trunk is a local
7	//!   bookmark at its `origin` position, so the sync a Land begins with
8	//!   has nothing to bring, and the branch descends from it, so the tree
9	//!   landed is the reviewed one. The branch's other bookmarks are named
10	//!   as merged and left as they are.
11	//! - [`run`] lands what the plan names: a conflicted target is refused,
12	//!   the trunk is fast-forwarded and pushed, and the cycle's bookmark is
13	//!   deleted, `--skip` keeping a side. A dry run makes every check and
14	//!   says each step, and does none: each step is its line and then the
15	//!   step behind `if !dry`, so a step added brings its dry-run line.
16	//!
17	//! `vc-x1 land -s b|p --source <BM|REV> --onto <BOOKMARK>` lands a cycle
18	//! whose last commit is already made, and `commit --closing ... --land`
19	//! plans its Land before the closing is made and runs it after, both
20	//! through these two.
21	//!
22	//! - `--source` names the cycle's last commit, a bookmark or a revision,
23	//!   and the cycle's bookmark by the rule [`cycle_bookmark`] states,
24	//!   `--closing`'s. Left out, it is the one local bookmark besides
25	//!   `--onto`, [`default_source`].
26	//! - `--onto` is any local bookmark `--source` descends from, so a
27	//!   bushy tree lands anywhere. Land only fast-forwards: a merge is
28	//!   `commit --closing`'s to make.
29	//! - `--delete-intermediate-bookmarks` deletes the bookmarks on the
30	//!   commits strictly between `--onto` and `--source`, the earlier
31	//!   cycles' of a stack landing together. Without it they are named as
32	//!   merged and kept, and a bookmark at the tip besides the cycle's is
33	//!   kept either way.
34	//! - The publish follows where the target is: the work `@-`, whose pair
35	//!   may be unfinished, goes through `push`, which finishes it, and a
36	//!   commit below it, whose pair is finished, by its trunk pushed alone
37	//!   and the agent `main` published.
38	
39	use std::path::{Path, PathBuf};
40	
41	use clap::Args;
42	use log::{debug, info};
43	
44	use crate::commit::Skip;
45	use crate::context::Context;
46	use crate::jj;
47	use crate::options_flags::dry_run::DryRunFlag;
48	use crate::options_flags::scope::{RepoScope, repo_scope_parser};
49	use crate::options_flags::squash::SquashSpec;
50	use crate::subcommand::SubcommandRunner;
51	
52	/// Land a cycle whose last commit is made: `--onto` fast-forwarded to
53	/// `--source` and pushed, and the cycle's bookmark deleted.
54	#[derive(Args, Debug)]
55	pub struct LandArgs {
56	    /// The cycle's last commit: a bookmark, the cycle's, or a revision,
57	    /// whose current bookmark, else its nearest parent's above `--onto`,
58	    /// is the cycle's [default: the one local bookmark besides `--onto`]
59	    #[arg(long, value_name = "BM|REV")]
60	    pub source: Option<String>,
61	
62	    /// The bookmark landed on, fast-forwarded to `--source`: a local
63	    /// bookmark at its `origin` position that `--source` descends from
64	    #[arg(long, value_name = "BOOKMARK", required = true)]
65	    pub onto: String,
66	
67	    /// Which side of the cycle's bookmark is kept: `local`, `remote`,
68	    /// or `both`, none deleted
69	    #[arg(long, value_enum, value_name = "SIDE", hide_possible_values = true)]
70	    pub skip: Option<Skip>,
71	
72	    /// Also delete the bookmarks on the commits strictly between `--onto`
73	    /// and `--source`, locally and on origin, as `--skip` allows: a stack
74	    /// of cycles landing together [default: named as merged and kept]
75	    #[arg(long)]
76	    pub delete_intermediate_bookmarks: bool,
77	
78	    /// Where: a path in the workspace for `-s b`, or the repo itself for
79	    /// `-s p` [default: the current directory]
80	    #[arg(short = 'R', long, value_name = "PATH")]
81	    pub repo: Option<PathBuf>,
82	
83	    /// Which repos, required: `b` a dual workspace's, `p` a plain repo
84	    #[arg(
85	        short = 's',
86	        long,
87	        value_name = "SCOPE",
88	        value_parser = repo_scope_parser(&["both", "por"]),
89	        required = true,
90	        help = "Which repos, required: `b|both` or `p|por`",
91	        long_help = "Which repos, required: `b|both` a dual workspace, or `p|por` a plain repo. \
92	                     `w` alone is refused, since it could publish trailers naming agent commits \
93	                     not yet published, and `a` alone, which has no cycle to land"
94	    )]
95	    pub scope: RepoScope,
96	
97	    /// Make every check and say each step, and change nothing
98	    #[command(flatten)]
99	    pub dry_run: DryRunFlag,
100	}
101	
102	/// Inputs to the land op, flat, owned, clap-free.
103	#[derive(Debug)]
104	pub struct LandParams {
105	    /// The work repo of `-s b`, or the plain repo of `-s p`.
106	    pub repo: PathBuf,
107	    pub scope: RepoScope,
108	    /// `None` is the one local bookmark besides `onto`.
109	    pub source: Option<String>,
110	    pub onto: String,
111	    pub skip: Option<Skip>,
112	    pub delete_intermediate: bool,
113	    pub dry_run: bool,
114	}
115	
116	impl TryFrom<&LandArgs> for LandParams {
117	    type Error = String;
118	
119	    /// Resolve the scope to the repo the Land moves bookmarks in.
120	    fn try_from(a: &LandArgs) -> Result<Self, String> {
121	        let repo = match &a.scope {
122	            RepoScope::Por => {
123	                let repos = crate::common::resolve_scoped_repos(&a.scope, a.repo.as_deref())
124	                    .map_err(|e| e.to_string())?;
125	                match repos.as_slice() {
126	                    [repo] => repo.clone(),
127	                    other => {
128	                        return Err(format!("land -s p: expected one repo, got {}", other.len()));
129	                    }
130	                }
131	            }
132	            RepoScope::Sides(sides) if sides.is_both() => {
133	                crate::pair::resolve_pair(a.repo.as_deref())
134	                    .map_err(|e| e.to_string())?
135	                    .work
136	            }
137	            RepoScope::Sides(_) => {
138	                return Err(
139	                    "land: a work-only Land would publish trailers naming agent commits its \
140	                     agent half may not have published, and the agent repo alone has no cycle to \
141	                     land, so the scope is `-s b`, or `-s p` for a plain repo"
142	                        .into(),
143	                );
144	            }
145	        };
146	        Ok(LandParams {
147	            repo,
148	            scope: a.scope.clone(),
149	            source: a.source.clone(),
150	            onto: a.onto.clone(),
151	            skip: a.skip,
152	            delete_intermediate: a.delete_intermediate_bookmarks,
153	            dry_run: a.dry_run.value,
154	        })
155	    }
156	}
157	
158	impl SubcommandRunner for LandArgs {
159	    type Params = LandParams;
160	
161	    /// Delegate to the `TryFrom<&LandArgs>` impl above.
162	    fn to_params(&self) -> Result<Self::Params, String> {
163	        LandParams::try_from(self)
164	    }
165	
166	    /// Run the `land` op.
167	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
168	        land(ctx, params)
169	    }
170	}
171	
172	/// Entry point: resolve `--source` and the cycle's bookmark, plan the
173	/// Land, refusing before anything moves, and run it.
174	pub fn land(ctx: &mut Context, params: &LandParams) -> Result<(), Box<dyn std::error::Error>> {
175	    debug!("land: enter {params:?}");
176	    let repo = params.repo.as_path();
177	    if !jj::local_bookmark_exists(repo, &params.onto)? {
178	        return Err(format!(
179	            "land: '{}' is not a local bookmark, and Land moves one",
180	            params.onto
181	        )
182	        .into());
183	    }
184	    let source = match &params.source {
185	        Some(s) => s.clone(),
186	        None => default_source(repo, &params.onto)?,
187	    };
188	    let tip = resolve_tip(repo, "land", &source)?;
189	    if jj::cid_of(repo, &params.onto)? == tip {
190	        return Err(format!(
191	            "land: '{}' is at '{source}' already, so there is nothing to land",
192	            params.onto
193	        )
194	        .into());
195	    }
196	    let bookmark = cycle_bookmark(repo, "land", "--source", &source, &params.onto, &tip)?;
197	    if bookmark.is_none() {
198	        info!(
199	            "land: no bookmark on the branch above '{}', so none is deleted",
200	            params.onto
201	        );
202	    }
203	    let plan = plan(
204	        repo,
205	        "land",
206	        params.onto.clone(),
207	        &tip,
208	        bookmark.as_deref(),
209	        params.skip,
210	        params.delete_intermediate,
211	    )?;
212	    run(
213	        ctx,
214	        repo,
215	        params.scope.clone(),
216	        &plan,
217	        &tip,
218	        &format!("'{source}'"),
219	        params.dry_run,
220	    )
221	}
222	
223	/// `--source` left out: the one local bookmark besides `onto`, refused
224	/// with the list when there are several, since naming one settles it.
225	pub(crate) fn default_source(
226	    repo: &Path,
227	    onto: &str,
228	) -> Result<String, Box<dyn std::error::Error>> {
229	    let mut found = jj::local_bookmarks_at(repo, "bookmarks()")?;
230	    found.retain(|b| b != onto);
231	    match found.as_slice() {
232	        [one] => {
233	            info!("land: --source is '{one}', the one local bookmark besides '{onto}'");
234	            Ok(one.clone())
235	        }
236	        [] => Err(format!(
237	            "land: there is no local bookmark besides '{onto}', so there is nothing to land"
238	        )
239	        .into()),
240	        several => Err(format!(
241	            "land: there are several local bookmarks besides '{onto}', {}, so which is the \
242	             source is not known: name it, --source <BM|REV>",
243	            several.join(", ")
244	        )
245	        .into()),
246	    }
247	}
248	
249	/// The one commit `arg` names, the cycle's tip, refused when it names
250	/// none or several.
251	pub(crate) fn resolve_tip(
252	    repo: &Path,
253	    label: &str,
254	    arg: &str,
255	) -> Result<String, Box<dyn std::error::Error>> {
256	    let cids = jj::cids_of(repo, arg).map_err(|e| {
257	        format!(
258	            "{label}: '{arg}' does not resolve in {}: {e}",
259	            repo.display()
260	        )
261	    })?;
262	    match cids.as_slice() {
263	        [one] => Ok(one.clone()),
264	        other => Err(format!(
265	            "{label}: '{arg}' names {} commits in {}, and a cycle's tip is exactly one",
266	            other.len(),
267	            repo.display()
268	        )
269	        .into()),
270	    }
271	}
272	
273	/// The cycle's bookmark, the one a Land deletes, decided by `arg`, the
274	/// argument of `flag` that names the tip: a bookmark named is that one;
275	/// a revision means the current bookmark on the tip, else the nearest
276	/// parent's, above `trunk`, several at that height refused with the
277	/// list, since naming one settles it, and none being none. The trunk
278	/// itself is never the cycle's.
279	pub(crate) fn cycle_bookmark(
280	    repo: &Path,
281	    label: &str,
282	    flag: &str,
283	    arg: &str,
284	    trunk: &str,
285	    tip: &str,
286	) -> Result<Option<String>, Box<dyn std::error::Error>> {
287	    if arg != trunk && jj::local_bookmark_exists(repo, arg)? {
288	        return Ok(Some(arg.to_string()));
289	    }
290	    let base = jj::cid_of(repo, trunk)?;
291	    let mut found =
292	        jj::local_bookmarks_at(repo, &format!("heads(({base}..({tip})) & bookmarks())"))?;
293	    found.retain(|b| *b != trunk);
294	    match found.len() {
295	        0 => Ok(None),
296	        1 => Ok(found.pop()),
297	        _ => Err(format!(
298	            "{label}: '{arg}' has several bookmarks at its nearest, {}, so which is the \
299	             cycle's is not known: name it, {flag} <BOOKMARK>",
300	            found.join(", ")
301	        )
302	        .into()),
303	    }
304	}
305	
306	/// A Land planned before anything is made: the trunk and where it is,
307	/// and the cycle's own bookmark, deleted after, `skip` keeping a side.
308	#[derive(Debug)]
309	pub(crate) struct LandPlan {
310	    /// How messages name the command, e.g. `commit --land`.
311	    pub label: &'static str,
312	    pub trunk: String,
313	    pub trunk_cid: String,
314	    pub topic: Option<String>,
315	    pub skip: Option<Skip>,
316	    /// The bookmarks strictly between the trunk and the tip, deleted
317	    /// after the cycle's when asked, `skip` keeping the same side.
318	    pub intermediate: Vec<String>,
319	    /// The branch's other bookmarks, merged by the Land and left as
320	    /// they are, named after it.
321	    pub merged: Vec<String>,
322	}
323	
324	/// Plan a Land of the branch read up to `tip` onto `trunk`, refusing
325	/// before anything is made. `bookmark` is the cycle's, deleted after,
326	/// and with `delete_intermediate` the bookmarks strictly between too.
327	pub(crate) fn plan(
328	    repo: &Path,
329	    label: &'static str,
330	    trunk: String,
331	    tip: &str,
332	    bookmark: Option<&str>,
333	    skip: Option<Skip>,
334	    delete_intermediate: bool,
335	) -> Result<LandPlan, Box<dyn std::error::Error>> {
336	    if !jj::local_bookmark_exists(repo, &trunk)? {
337	        return Err(
338	            format!("{label}: '{trunk}' is not a local bookmark, and Land moves one").into(),
339	        );
340	    }
341	    let trunk_cid = jj::cid_of(repo, &trunk)?;
342	    let remote = jj::remote_bookmark_targets(repo, "origin")?
343	        .get(&trunk)
344	        .cloned();
345	    if remote.as_deref() != Some(trunk_cid.as_str()) {
346	        return Err(format!(
347	            "{label}: '{trunk}' is at {trunk_cid} locally and {} on origin: sync first, \
348	             since a trunk that moved stops a Land",
349	            remote.as_deref().unwrap_or("absent")
350	        )
351	        .into());
352	    }
353	    if !jj::matches(repo, &format!("{trunk_cid} & ::({tip})"))? {
354	        return Err(format!(
355	            "{label}: the branch does not descend from '{trunk}' at {trunk_cid}, so the \
356	             trunk moved since the fork and the Land would carry a tree no validation saw: rebase \
357	             the branch onto it first"
358	        )
359	        .into());
360	    }
361	    let topic = bookmark.map(str::to_string);
362	    let others = |revset: &str| -> Result<Vec<String>, Box<dyn std::error::Error>> {
363	        let mut found = jj::local_bookmarks_at(repo, revset)?;
364	        found.retain(|b| *b != trunk && Some(b) != topic.as_ref());
365	        Ok(found)
366	    };
367	    let between = others(&format!("(({trunk_cid}..({tip})) ~ ({tip})) & bookmarks()"))?;
368	    let mut merged = others(&format!("({tip}) & bookmarks()"))?;
369	    let intermediate = if delete_intermediate {
370	        between
371	    } else {
372	        merged.splice(0..0, between);
373	        Vec::new()
374	    };
375	    info!(
376	        "{label}: land onto '{trunk}' at {trunk_cid}, the cycle's bookmark {}",
377	        topic
378	            .as_deref()
379	            .map(|t| format!("'{t}'"))
380	            .unwrap_or_else(|| "none".into())
381	    );
382	    Ok(LandPlan {
383	        label,
384	        trunk,
385	        trunk_cid,
386	        topic,
387	        skip,
388	        intermediate,
389	        merged,
390	    })
391	}
392	
393	/// Land what `land` plans onto `target`, named `what` in messages:
394	/// refuse a conflicted target, fast-forward the trunk to it, publish
395	/// it, `scope` saying which repos, and delete the cycle's bookmark,
396	/// `--skip` keeping a side. A dry run makes every check and says each
397	/// step, and does none.
398	pub(crate) fn run(
399	    ctx: &mut Context,
400	    repo: &Path,
401	    scope: RepoScope,
402	    land: &LandPlan,
403	    target: &str,
404	    what: &str,
405	    dry: bool,
406	) -> Result<(), Box<dyn std::error::Error>> {
407	    let LandPlan {
408	        label,
409	        trunk,
410	        trunk_cid,
411	        topic,
412	        skip,
413	        intermediate,
414	        merged,
415	    } = land;
416	    let keep = match skip {
417	        Some(Skip::Both) => None,
418	        Some(Skip::Local) => Some(Some(crate::delete_bookmark::Keep::Local)),
419	        Some(Skip::Remote) => Some(Some(crate::delete_bookmark::Keep::Remote)),
420	        None => Some(None),
421	    };
422	    // Checks run in both modes, so a dry run refuses what a Land would.
423	    if jj::matches(repo, &format!("({target}) & conflicts()"))? {
424	        return Err(format!(
425	            "{label}: {what} is conflicted, so it is not landed: resolve it, then \
426	             land it with `vc-x1 move-bookmark --bookmark {trunk} --target {target}` and \
427	             `vc-x1 push`"
428	        )
429	        .into());
430	    }
431	    // Each step's line, then the step, which a dry run leaves undone.
432	    let tag = if dry { " [dry-run]" } else { "" };
433	    // The work @-'s pair may be unfinished, which push finishes. A
434	    // commit below it has a finished pair, so its trunk goes alone.
435	    let at_work_head = jj::matches(repo, &format!("({target}) & @-"))?;
436	    info!("{label}:{tag} fast-forward '{trunk}' from {trunk_cid} to {what}");
437	    if !dry {
438	        ctx.session(repo)?.bookmark_set(trunk, target)?;
439	    }
440	    if at_work_head {
441	        info!("{label}:{tag} push '{trunk}', the work @-, with its pair");
442	        if !dry {
443	            crate::push::push(
444	                ctx,
445	                &crate::push::PushParams {
446	                    revision: None,
447	                    bookmark: Some(trunk.clone()),
448	                    repo: Some(repo.to_path_buf()),
449	                    scope,
450	                    step: false,
451	                    dry_run: false,
452	                    yes: true,
453	                },
454	            )?;
455	        }
456	    } else {
457	        info!("{label}:{tag} push '{trunk}'");
458	        if !dry {
459	            crate::common::verify_tracking(repo, trunk)?;
460	            ctx.session(repo)?.git_push_bookmark(trunk)?;
461	        }
462	        if scope != RepoScope::Por {
463	            let agent = crate::pair::resolve_pair(Some(repo))?.agent;
464	            info!("{label}:{tag} publish the agent main");
465	            if !dry {
466	                crate::squash_push::squash_push(
467	                    ctx,
468	                    &crate::squash_push::SquashPushParams {
469	                        repo: agent,
470	                        squash: SquashSpec {
471	                            source: "@".to_string(),
472	                            target: "@-".to_string(),
473	                        },
474	                        bookmark: "main".to_string(),
475	                        at_rest: false,
476	                        yes: true,
477	                        dry_run: false,
478	                    },
479	                )?;
480	            }
481	        }
482	    }
483	    if let (Some(t), Some(keep)) = (topic, keep) {
484	        info!("{label}:{tag} delete '{t}'");
485	        if !dry {
486	            crate::delete_bookmark::delete_bookmark(ctx, repo, t, keep, false)?;
487	        }
488	    }
489	    if let Some(keep) = keep {
490	        for b in intermediate {
491	            info!("{label}:{tag} delete '{b}', between '{trunk}' and {what}");
492	            if !dry {
493	                crate::delete_bookmark::delete_bookmark(ctx, repo, b, keep, false)?;
494	            }
495	        }
496	    }
497	    if !merged.is_empty() {
498	        info!(
499	            "{label}:{tag} merged into '{trunk}' and left as they are, yours to keep or \
500	             delete: {}",
501	            merged.join(", ")
502	        );
503	    }
504	    if !dry {
505	        info!(
506	            "{label}: landed on '{trunk}', the undo being a revert, the trunk having moved \
507	             from {trunk_cid}. `vc-x1 install` installs the artifact"
508	        );
509	    }
510	    Ok(())
511	}
