1	//! `push` subcommand: publish a rung's pair. It carries no
2	//! description and writes none, so what was reviewed is what goes
3	//! out.
4	//!
5	//! `vc-x1 commit` makes the pair, the work commit and the agent
6	//! commit, each naming the other, or the work half alone with its
7	//! trailer naming the agent `@`. Each trailer is fixed before push
8	//! runs, so the two halves are independent, and `push -s b` is
9	//! `push -s a` then `push -s w`, the order the pair is completed in:
10	//!
11	//! - the agent half completes the agent commit by the state it
12	//!   finds, folding the journal into a committed partner (`commit
13	//!   -s b`), or committing it as the partner with the work commit's
14	//!   own text when the agent `@` is the change the work commit names
15	//!   (`commit -s w`) or the agent repo changed since, then sets and
16	//!   pushes `main`;
17	//! - the work half checks its trailer names the partner, restamping
18	//!   the unpublished work commit when it does not, said out loud,
19	//!   then sets and pushes the bookmark `@-` sits on, or the one
20	//!   named, a new name created there.
21	//!
22	//! Before either: a work `@` that is not empty is refused, being a
23	//! fix to fold or the next rung, the user's call, and so is a work
24	//! `@-` with no `ochid:` trailer, which is not a pair's commit. Each
25	//! half restores the repo it touched from a `jj op` snapshot when a
26	//! stage fails before its own push, and from a push on the remote
27	//! boundary is crossed. Rerunning is always safe: a half whose work
28	//! is done finds nothing to do.
29	//!
30	//! `-r` names another commit, already made, and only a name goes out
31	//! for it, the bookmark at it or a new one: the pair's checks are the
32	//! work `@-`'s.
33	//!
34	//! `-s` is required: `b` both halves, `a` the agent half, `w` the
35	//! work half, and `p` a plain repo's `@-` on its bookmark, no
36	//! trailer asked for.
37	
38	use std::path::{Path, PathBuf};
39	
40	use clap::Args;
41	use log::{debug, info, warn};
42	
43	use crate::common::prompt;
44	use crate::context::Context;
45	use crate::desc_helpers::with_trailer;
46	use crate::jj;
47	use crate::options_flags::retired_positional::refusal;
48	use crate::options_flags::scope::{
49	    ALL_REPO_SCOPES, REPO_SCOPE_FORMS, RepoScope, Scope, repo_scope_parser,
50	};
51	use crate::options_flags::squash::SquashSpec;
52	use crate::pair::{Pair, Partner, Snapshot, WorkCommit, is_published, resolve_pair};
53	use crate::subcommand::SubcommandRunner;
54	
55	/// Bookmark the agent repo always advances and pushes. The agent
56	/// repo is a linear journal on `main` by design: `<bookmark>` names
57	/// a work-repo bookmark only.
58	const BOT_BOOKMARK: &str = "main";
59	
60	/// The commit push publishes when `-r` is left out: the work commit of
61	/// the pair `commit` made.
62	const WORK_COMMIT: &str = "@-";
63	
64	/// CLI arguments for the `push` subcommand.
65	#[derive(Args, Debug)]
66	pub struct PushArgs {
67	    /// Retired: the bookmark, now `--bookmark`, or a revision, now
68	    /// `-r`, refused naming the one it was.
69	    #[arg(value_name = "RETIRED", hide = true)]
70	    pub retired: Option<String>,
71	
72	    /// The commit to publish, one: `@-` publishes the pair, any other
73	    /// a name alone [default: `@-`]
74	    #[arg(short = 'r', long, value_name = "REV")]
75	    pub revision: Option<String>,
76	
77	    /// The remote's name for it: a bookmark on the line, moved there,
78	    /// one already at REV, or a new name, created there [default: the
79	    /// line's bookmark, or the one at REV]
80	    #[arg(long, value_name = "NAME")]
81	    pub bookmark: Option<String>,
82	
83	    /// Where: a path in the workspace for `-s b|w|a`, its root or
84	    /// either repo, or the repo itself for `-s p` [default: the
85	    /// current directory]
86	    #[arg(short = 'R', long, value_name = "PATH")]
87	    pub repo: Option<PathBuf>,
88	
89	    /// Which repos, required: `b|both` publishes the pair, `w|work`
90	    /// the work half, `a|agent` the agent half, `p|por` a plain repo
91	    #[arg(
92	        short = 's',
93	        long,
94	        value_name = "SCOPE",
95	        value_parser = repo_scope_parser(ALL_REPO_SCOPES),
96	        required = true,
97	        help = format!("Which repos, required: {REPO_SCOPE_FORMS}")
98	    )]
99	    pub scope: RepoScope,
100	
101	    /// Pause between every stage for an interactive approval gate.
102	    #[arg(long)]
103	    pub step: bool,
104	
105	    /// Print the exact commands for every stage without side effects.
106	    #[arg(long)]
107	    pub dry_run: bool,
108	
109	    /// Pass the `--step` gates without asking.
110	    #[arg(short = 'y', long)]
111	    pub yes: bool,
112	}
113	
114	/// Inputs to the push op, flat, owned, clap-free, straight over from
115	/// the flags.
116	pub struct PushParams {
117	    pub revision: Option<String>,
118	    pub bookmark: Option<String>,
119	    pub repo: Option<PathBuf>,
120	    pub scope: RepoScope,
121	    pub step: bool,
122	    pub dry_run: bool,
123	    pub yes: bool,
124	}
125	
126	/// What a run published, for the completion check: the work
127	/// bookmark with the work commit's change id, and the partner the
128	/// agent `main` ends at, each `None` when the scope left its half
129	/// out. `held` is a work `@` holding new work when the run began,
130	/// which push leaves as it is.
131	struct Run {
132	    work: Option<(String, String)>,
133	    partner: Option<String>,
134	    held: bool,
135	}
136	
137	impl From<&PushArgs> for PushParams {
138	    /// The flags straight over; the retired positional is
139	    /// `to_params`'s to refuse.
140	    fn from(a: &PushArgs) -> Self {
141	        Self {
142	            revision: a.revision.clone(),
143	            bookmark: a.bookmark.clone(),
144	            repo: a.repo.clone(),
145	            scope: a.scope.clone(),
146	            step: a.step,
147	            dry_run: a.dry_run,
148	            yes: a.yes,
149	        }
150	    }
151	}
152	
153	impl SubcommandRunner for PushArgs {
154	    type Params = PushParams;
155	
156	    /// Refuse the retired positional, else delegate to the
157	    /// `From<&PushArgs>` impl above.
158	    fn to_params(&self) -> Result<Self::Params, String> {
159	        if let Some(value) = &self.retired {
160	            return Err(retired_refusal(self.repo.as_deref(), value));
161	        }
162	        Ok(PushParams::from(self))
163	    }
164	
165	    /// Run the `push` op.
166	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
167	        push(ctx, params)
168	    }
169	}
170	
171	/// Whether `stdin` is attached to a terminal, for the `--step` gates.
172	fn is_stdin_tty() -> bool {
173	    crate::common::is_stdin_tty()
174	}
175	
176	/// The refusal for the retired positional: `--bookmark` when `value`
177	/// is a bookmark in the repo push runs in, which is what it meant, else
178	/// `-r`, a revision being the other thing it could be.
179	fn retired_refusal(repo: Option<&Path>, value: &str) -> String {
180	    let repo = repo.unwrap_or(Path::new(".")); // OK: no -R is the current directory
181	    // OK: a failed lookup only loses the hint, so it reads as no bookmark
182	    let is_bookmark = jj::local_bookmark_exists(repo, value).unwrap_or(false);
183	    refusal("push", value, if is_bookmark { "--bookmark" } else { "-r" })
184	}
185	
186	/// The commit push publishes: `-r`'s, else the work `@-`.
187	fn revision(params: &PushParams) -> &str {
188	    params.revision.as_deref().unwrap_or(WORK_COMMIT) // OK: `-r` left out is the `@-`
189	}
190	
191	/// Entry point for the `push` subcommand: resolve `-s` and `-R` and
192	/// publish.
193	pub fn push(ctx: &mut Context, params: &PushParams) -> Result<(), Box<dyn std::error::Error>> {
194	    match &params.scope {
195	        RepoScope::Por => {
196	            let repos = crate::common::resolve_scoped_repos(&params.scope, params.repo.as_deref())?;
197	            let [repo] = repos.as_slice() else {
198	                return Err(format!("push -s p: expected one repo, got {}", repos.len()).into());
199	            };
200	            refuse_a_revision(repo, params)?;
201	            if publish_elsewhere(ctx, repo, params)? {
202	                return Ok(());
203	            }
204	            push_por(ctx, repo, params)
205	        }
206	        RepoScope::Sides(sides) => {
207	            // Both paths whatever the side: a half still needs the
208	            // other repo to find or name its partner.
209	            let pair = resolve_pair(params.repo.as_deref())?;
210	            refuse_a_revision(&pair.work, params)?;
211	            if !sides.has_work() {
212	                if let Some(rev) = &params.revision {
213	                    return Err(format!(
214	                        "push -s a: the agent half publishes the agent `main`, so `-r {rev}` names \
215	                         nothing. `-s b` or `-s w` publishes a work commit"
216	                    )
217	                    .into());
218	                }
219	            } else if publish_elsewhere(ctx, &pair.work, params)? {
220	                return Ok(());
221	            }
222	            push_in(ctx, &pair, sides, params)
223	        }
224	    }
225	}
226	
227	/// Refuse a `--bookmark` that is no bookmark but a revision, such as
228	/// `@-`: the flag names the remote's name, and `-r` the commit.
229	fn refuse_a_revision(repo: &Path, params: &PushParams) -> Result<(), Box<dyn std::error::Error>> {
230	    let Some(name) = &params.bookmark else {
231	        return Ok(());
232	    };
233	    if jj::local_bookmark_exists(repo, name)? || !jj::rev_exists(repo, name)? {
234	        return Ok(());
235	    }
236	    Err(format!(
237	        "push: '{name}' is a revision, not a bookmark name: `-r {name}` names the commit to \
238	         publish, and `--bookmark` its name on the remote"
239	    )
240	    .into())
241	}
242	
243	/// A REV other than the work `@-`, a commit already made: publish a
244	/// name for it and no pair, since the pair's checks, its trailer, its
245	/// partner, and the restamp, are the `@-`'s. True when it was this
246	/// case. The name is the one bookmark at REV, or `--bookmark`'s, that
247	/// bookmark or a new one created there. REV must be one commit, and
248	/// the working copy, which holds changes not yet committed, and the
249	/// root, which has nothing to publish, are refused, `vc-x1 commit`
250	/// being what turns the working copy into a commit.
251	fn publish_elsewhere(
252	    ctx: &mut Context,
253	    repo: &Path,
254	    params: &PushParams,
255	) -> Result<bool, Box<dyn std::error::Error>> {
256	    let rev = revision(params);
257	    let cids = jj::cids_of(repo, rev)?;
258	    let at = match cids.as_slice() {
259	        [one] => one.clone(),
260	        [] => return Err(format!("push: -r '{rev}' resolves to no commit").into()),
261	        many => {
262	            return Err(format!(
263	                "push: -r '{rev}' resolves to {} commits, and push publishes one",
264	                many.len()
265	            )
266	            .into());
267	        }
268	    };
269	    if at == jj::cid_of(repo, WORK_COMMIT)? {
270	        return Ok(false);
271	    }
272	    if at == jj::cid_of(repo, "@")? {
273	        return Err(format!(
274	            "push: -r '{rev}' is the working copy, which is not committed: `vc-x1 commit` \
275	             commits it and pushes it"
276	        )
277	        .into());
278	    }
279	    if at == jj::cid_of(repo, "root()")? {
280	        return Err(
281	            format!("push: -r '{rev}' is the root commit, which has nothing to publish").into(),
282	        );
283	    }
284	    let at_rev = jj::local_bookmarks_at(repo, &at)?;
285	    let (name, new) = match &params.bookmark {
286	        Some(name) if at_rev.contains(name) => (name.clone(), false),
287	        Some(name) if jj::local_bookmark_exists(repo, name)? => {
288	            return Err(format!(
289	                "push: bookmark '{name}' is not at -r '{rev}': push publishes a name where it \
290	                 is, or a new one created there, and `vc-x1 move-bookmark` moves one"
291	            )
292	            .into());
293	        }
294	        Some(name) => (name.clone(), true),
295	        None => match at_rev.as_slice() {
296	            [one] => (one.clone(), false),
297	            [] => {
298	                return Err(format!(
299	                    "push: -r '{rev}' carries no bookmark, so name one with --bookmark, which \
300	                     is created there"
301	                )
302	                .into());
303	            }
304	            many => {
305	                return Err(format!(
306	                    "push: -r '{rev}' carries several bookmarks: {}, so name the one with \
307	                     --bookmark",
308	                    many.join(", ")
309	                )
310	                .into());
311	            }
312	        },
313	    };
314	    let short = jj::cid_short_of(repo, &at)?;
315	    let dry = if params.dry_run { "[dry-run] " } else { "" };
316	    if new {
317	        info!("push: {dry}create '{name}' at {short}, a commit already made, and push it");
318	    } else {
319	        info!("push: {dry}publish '{name}' where it is, {short}, a commit already made");
320	    }
321	    if params.dry_run {
322	        return Ok(true);
323	    }
324	    if new {
325	        ctx.session(repo)?.bookmark_set(&name, &at)?;
326	    } else {
327	        crate::common::verify_tracking(repo, &name)?;
328	    }
329	    ctx.session(repo)?.git_push_bookmark(&name)?;
330	    Ok(true)
331	}
332	
333	/// `push` on a dual workspace, parameterized on the pair and the
334	/// sides to publish. CLI dispatch resolves these from `-s` and `-R`,
335	/// and integration tests pass a fixture's pair.
336	///
337	/// The checks every half needs run first, then the agent half, then
338	/// the work half, each restoring its own repo on a local failure.
339	pub(crate) fn push_in(
340	    ctx: &mut Context,
341	    pair: &Pair,
342	    sides: &Scope,
343	    params: &PushParams,
344	) -> Result<(), Box<dyn std::error::Error>> {
345	    if params.dry_run {
346	        info!("push: DRY-RUN: no side effects (no commits, no pushes)");
347	    }
348	    // The dual-mode preflight: both repos' recorded topology agrees.
349	    crate::common::require_bot_dir(&pair.work)?;
350	    // New work in the work `@` is the next rung's, and push publishes
351	    // `@-`, so it is left as it is.
352	    let held = sides.has_work() && !jj::is_empty(&pair.work, "@")?;
353	    if held {
354	        info!("push: the work @ holds new work, left as it is, and @- is what goes out");
355	    }
356	    let Some(work) = crate::pair::work_commit(pair)? else {
357	        return Err(
358	            "push: the work repo's @- carries no `ochid:` trailer, so it is not a \
359	                    pair's commit. Make the pair with `vc-x1 commit -s b` or `-s w` first"
360	                .into(),
361	        );
362	    };
363	    // The bookmark first, so a run whose work half cannot publish
364	    // stops before the agent half publishes anything.
365	    let bookmark = if sides.has_work() {
366	        Some(resolve_bookmark(&pair.work, params)?)
367	    } else {
368	        None
369	    };
370	
371	    let partner = if sides.has_bot() {
372	        Some(agent_half(ctx, pair, &work, params)?)
373	    } else {
374	        None
375	    };
376	    if let Some(bookmark) = &bookmark {
377	        if sides.has_bot() {
378	            step_gate(params, "the agent half", "the work half")?;
379	        }
380	        work_half(ctx, pair, &work, bookmark, params)?;
381	    }
382	
383	    if params.dry_run {
384	        info!("push: DRY-RUN complete: no changes written");
385	        return Ok(());
386	    }
387	    // Honest completion, warning-only: the remote boundary is crossed
388	    // by now, so the user investigates rather than a rollback.
389	    let run = Run {
390	        work: bookmark.map(|b| (b, work.chid.clone())),
391	        partner,
392	        held,
393	    };
394	    match verify_completion(pair, &run) {
395	        Ok(()) => info!("push: completed all stages (verified)"),
396	        Err(e) => {
397	            warn!("push: completed stages but post-completion verification failed:");
398	            warn!("  {e}");
399	            warn!("  investigate the discrepancy before the next push");
400	        }
401	    }
402	    Ok(())
403	}
