435	/// The agent half: complete the partner by the state found, then set
436	/// and push `main`. Returns the partner's change id, where `main`
437	/// ends.
438	fn agent_half(
439	    ctx: &mut Context,
440	    pair: &Pair,
441	    work: &WorkCommit,
442	    params: &PushParams,
443	) -> Result<String, Box<dyn std::error::Error>> {
444	    // The intent lines carry the dry-run tag too, or they read as done.
445	    let dry = if params.dry_run { "[dry-run] " } else { "" };
446	    let (partner, commit_journal) = match crate::pair::partner(pair, work)? {
447	        Partner::Committed(partner) => {
448	            info!(
449	                "push agent: {dry}fold the journal into the partner at @- {partner}, which names the \
450	                 work commit, and publish {BOT_BOOKMARK}"
451	            );
452	            (partner, false)
453	        }
454	        Partner::Pending(agent_at) => {
455	            info!(
456	                "push agent: {dry}commit the agent @ {agent_at} as the partner, the change the work \
457	                 commit names, and publish {BOT_BOOKMARK}"
458	            );
459	            (agent_at, true)
460	        }
461	        Partner::Changed { stamped, agent_at } => {
462	            // The work half will restamp, which a published work
463	            // commit cannot take, so stop before anything moves.
464	            if is_published(&pair.work, "@-")? {
465	                return Err(
466	                    "push: the work @- is published and names an agent change that is \
467	                            no longer the partner, so it cannot be restamped. Put the agent repo \
468	                            back at the change it names, or make a new pair"
469	                        .into(),
470	                );
471	            }
472	            warn!(
473	                "push agent: {dry}the work commit names {stamped}, which is neither the agent @ nor \
474	                 the partner at @-, so the agent repo changed since the commit. Commit the agent \
475	                 @ {agent_at} as the partner and publish {BOT_BOOKMARK}, and the work half \
476	                 restamps the work commit to name it"
477	            );
478	            (agent_at, true)
479	        }
480	    };
481	    let agent_arg = pair.agent.to_string_lossy();
482	    if params.dry_run {
483	        if commit_journal {
484	            info!("push agent: [dry-run] would run jj commit -R {agent_arg} -m <work text+ochid>");
485	        }
486	        info!("push agent: [dry-run] would squash @ -> @- and push {BOT_BOOKMARK} -R {agent_arg}");
487	        return Ok(partner);
488	    }
489	    if commit_journal {
490	        let text = without_trailers(&jj::desc_of(&pair.work, "@-")?);
491	        let desc = with_trailer(
492	            &text,
493	            &crate::desc_helpers::ochid_value_in_form(
494	                crate::desc_helpers::is_url_form(&work.trailer),
495	                &pair.work,
496	                &work.chid,
497	            )?,
498	        );
499	        let snapshot = Snapshot::take(&pair.agent)?;
500	        info!("push agent: commit -R {agent_arg}");
501	        if let Err(e) = ctx.session(&pair.agent)?.commit(&desc) {
502	            snapshot.restore("push agent", e.as_ref());
503	            return Err(e);
504	        }
505	        step_gate(params, "the agent commit", "the agent publish")?;
506	    }
507	    info!("push agent: squash @ -> @- + push {BOT_BOOKMARK} -R {agent_arg}");
508	    let sp = crate::squash_push::SquashPushParams {
509	        repo: pair.agent.clone(),
510	        squash: SquashSpec {
511	            source: "@".to_string(),
512	            target: "@-".to_string(),
513	        },
514	        bookmark: BOT_BOOKMARK.to_string(),
515	        // Mid-push the mismatch is the normal state, since this stage
516	        // is what publishes main: don't report a lost publish.
517	        at_rest: false,
518	        yes: true,
519	        dry_run: false,
520	    };
521	    crate::squash_push::squash_push(ctx, &sp)?;
522	    Ok(partner)
523	}
