114	/// Inputs to the push op, flat, owned, clap-free, straight over from
115	/// the flags.
116	pub struct PushParams {
117	    pub revision: Option<String>,
118	    pub bookmark: Option<String>,
119	    pub repo: Option<PathBuf>,
120	    pub scope: RepoScope,
121	    pub step: bool,
122	    pub dry_run: bool,
123	    pub yes: bool,
124	}
