137	impl From<&PushArgs> for PushParams {
138	    /// The flags straight over; the retired positional is
139	    /// `to_params`'s to refuse.
140	    fn from(a: &PushArgs) -> Self {
141	        Self {
142	            revision: a.revision.clone(),
143	            bookmark: a.bookmark.clone(),
144	            repo: a.repo.clone(),
145	            scope: a.scope.clone(),
146	            step: a.step,
147	            dry_run: a.dry_run,
148	            yes: a.yes,
149	        }
150	    }
