227	/// Refuse a `--bookmark` that is no bookmark but a revision, such as
228	/// `@-`: the flag names the remote's name, and `-r` the commit.
229	fn refuse_a_revision(repo: &Path, params: &PushParams) -> Result<(), Box<dyn std::error::Error>> {
230	    let Some(name) = &params.bookmark else {
231	        return Ok(());
232	    };
233	    if jj::local_bookmark_exists(repo, name)? || !jj::rev_exists(repo, name)? {
234	        return Ok(());
235	    }
236	    Err(format!(
237	        "push: '{name}' is a revision, not a bookmark name: `-r {name}` names the commit to \
238	         publish, and `--bookmark` its name on the remote"
239	    )
240	    .into())
241	}
242	
243	/// A REV other than the work `@-`, a commit already made: publish a
244	/// name for it and no pair, since the pair's checks, its trailer, its
245	/// partner, and the restamp, are the `@-`'s. True when it was this
246	/// case. The name is the one bookmark at REV, or `--bookmark`'s, that
247	/// bookmark or a new one created there. REV must be one commit, and
248	/// the working copy, which holds changes not yet committed, and the
249	/// root, which has nothing to publish, are refused, `vc-x1 commit`
250	/// being what turns the working copy into a commit.
251	fn publish_elsewhere(
252	    ctx: &mut Context,
253	    repo: &Path,
254	    params: &PushParams,
255	) -> Result<bool, Box<dyn std::error::Error>> {
256	    let rev = revision(params);
257	    let cids = jj::cids_of(repo, rev)?;
258	    let at = match cids.as_slice() {
259	        [one] => one.clone(),
260	        [] => return Err(format!("push: -r '{rev}' resolves to no commit").into()),
261	        many => {
262	            return Err(format!(
263	                "push: -r '{rev}' resolves to {} commits, and push publishes one",
264	                many.len()
265	            )
266	            .into());
267	        }
268	    };
269	    if at == jj::cid_of(repo, WORK_COMMIT)? {
270	        return Ok(false);
271	    }
272	    if at == jj::cid_of(repo, "@")? {
273	        return Err(format!(
274	            "push: -r '{rev}' is the working copy, which is not committed: `vc-x1 commit` \
275	             commits it and pushes it"
276	        )
277	        .into());
278	    }
279	    if at == jj::cid_of(repo, "root()")? {
280	        return Err(
281	            format!("push: -r '{rev}' is the root commit, which has nothing to publish").into(),
282	        );
283	    }
284	    let at_rev = jj::local_bookmarks_at(repo, &at)?;
285	    let (name, new) = match &params.bookmark {
286	        Some(name) if at_rev.contains(name) => (name.clone(), false),
287	        Some(name) if jj::local_bookmark_exists(repo, name)? => {
288	            return Err(format!(
289	                "push: bookmark '{name}' is not at -r '{rev}': push publishes a name where it \
290	                 is, or a new one created there, and `vc-x1 move-bookmark` moves one"
291	            )
292	            .into());
293	        }
294	        Some(name) => (name.clone(), true),
295	        None => match at_rev.as_slice() {
296	            [one] => (one.clone(), false),
297	            [] => {
298	                return Err(format!(
299	                    "push: -r '{rev}' carries no bookmark, so name one with --bookmark, which \
300	                     is created there"
301	                )
302	                .into());
303	            }
304	            many => {
305	                return Err(format!(
306	                    "push: -r '{rev}' carries several bookmarks: {}, so name the one with \
307	                     --bookmark",
308	                    many.join(", ")
309	                )
310	                .into());
311	            }
312	        },
313	    };
314	    let short = jj::cid_short_of(repo, &at)?;
315	    let dry = if params.dry_run { "[dry-run] " } else { "" };
316	    if new {
317	        info!("push: {dry}create '{name}' at {short}, a commit already made, and push it");
318	    } else {
319	        info!("push: {dry}publish '{name}' where it is, {short}, a commit already made");
320	    }
321	    if params.dry_run {
322	        return Ok(true);
323	    }
324	    if new {
325	        ctx.session(repo)?.bookmark_set(&name, &at)?;
326	    } else {
327	        crate::common::verify_tracking(repo, &name)?;
328	    }
329	    ctx.session(repo)?.git_push_bookmark(&name)?;
330	    Ok(true)
331	}
