405	/// The bookmark `@-` goes out on: the one named, which must be among
406	/// the nearest bookmarks below `@-` or a new name, set there by the
407	/// push, else the line's own.
408	fn resolve_bookmark(
409	    root: &Path,
410	    params: &PushParams,
411	) -> Result<String, Box<dyn std::error::Error>> {
412	    match &params.bookmark {
413	        Some(b) => {
414	            if !jj::local_bookmark_exists(root, b)? {
415	                let dry = if params.dry_run { "[dry-run] " } else { "" };
416	                info!("push: {dry}'{b}' is a new name, created at @- and pushed tracked");
417	                return Ok(b.clone());
418	            }
419	            let nearest = jj::local_bookmarks_at(root, "heads(::@- & bookmarks())")?;
420	            if !nearest.contains(b) {
421	                return Err(format!(
422	                    "push: bookmark '{b}' is not the nearest bookmark below @-, the line's own \
423	                     ({}). Name one of them, a new name to create at @-, or none to use the \
424	                     line's, and `-r {b}` publishes it where it is",
425	                    nearest.join(", ")
426	                )
427	                .into());
428	            }
429	            Ok(b.clone())
430	        }
431	        None => crate::squash_push::current_bookmark(root, WORK_COMMIT),
432	    }
433	}
434	
435	/// The agent half: complete the partner by the state found, then set
436	/// and push `main`. Returns the partner's change id, where `main`
437	/// ends.
438	fn agent_half(
439	    ctx: &mut Context,
440	    pair: &Pair,
441	    work: &WorkCommit,
442	    params: &PushParams,
443	) -> Result<String, Box<dyn std::error::Error>> {
444	    // The intent lines carry the dry-run tag too, or they read as done.
445	    let dry = if params.dry_run { "[dry-run] " } else { "" };
446	    let (partner, commit_journal) = match crate::pair::partner(pair, work)? {
447	        Partner::Committed(partner) => {
448	            info!(
449	                "push agent: {dry}fold the journal into the partner at @- {partner}, which names the \
450	                 work commit, and publish {BOT_BOOKMARK}"
451	            );
452	            (partner, false)
453	        }
454	        Partner::Pending(agent_at) => {
455	            info!(
456	                "push agent: {dry}commit the agent @ {agent_at} as the partner, the change the work \
457	                 commit names, and publish {BOT_BOOKMARK}"
458	            );
459	            (agent_at, true)
460	        }
461	        Partner::Changed { stamped, agent_at } => {
462	            // The work half will restamp, which a published work
463	            // commit cannot take, so stop before anything moves.
464	            if is_published(&pair.work, "@-")? {
465	                return Err(
466	                    "push: the work @- is published and names an agent change that is \
467	                            no longer the partner, so it cannot be restamped. Put the agent repo \
468	                            back at the change it names, or make a new pair"
469	                        .into(),
470	                );
471	            }
472	            warn!(
473	                "push agent: {dry}the work commit names {stamped}, which is neither the agent @ nor \
474	                 the partner at @-, so the agent repo changed since the commit. Commit the agent \
475	                 @ {agent_at} as the partner and publish {BOT_BOOKMARK}, and the work half \
476	                 restamps the work commit to name it"
477	            );
478	            (agent_at, true)
479	        }
480	    };
481	    let agent_arg = pair.agent.to_string_lossy();
482	    if params.dry_run {
483	        if commit_journal {
484	            info!("push agent: [dry-run] would run jj commit -R {agent_arg} -m <work text+ochid>");
485	        }
486	        info!("push agent: [dry-run] would squash @ -> @- and push {BOT_BOOKMARK} -R {agent_arg}");
487	        return Ok(partner);
488	    }
489	    if commit_journal {
490	        let text = without_trailers(&jj::desc_of(&pair.work, "@-")?);
491	        let desc = with_trailer(
492	            &text,
493	            &crate::desc_helpers::ochid_value_in_form(
494	                crate::desc_helpers::is_url_form(&work.trailer),
495	                &pair.work,
496	                &work.chid,
497	            )?,
498	        );
499	        let snapshot = Snapshot::take(&pair.agent)?;
500	        info!("push agent: commit -R {agent_arg}");
501	        if let Err(e) = ctx.session(&pair.agent)?.commit(&desc) {
502	            snapshot.restore("push agent", e.as_ref());
503	            return Err(e);
504	        }
505	        step_gate(params, "the agent commit", "the agent publish")?;
506	    }
507	    info!("push agent: squash @ -> @- + push {BOT_BOOKMARK} -R {agent_arg}");
508	    let sp = crate::squash_push::SquashPushParams {
509	        repo: pair.agent.clone(),
510	        squash: SquashSpec {
511	            source: "@".to_string(),
512	            target: "@-".to_string(),
513	        },
514	        bookmark: BOT_BOOKMARK.to_string(),
515	        // Mid-push the mismatch is the normal state, since this stage
516	        // is what publishes main: don't report a lost publish.
517	        at_rest: false,
518	        yes: true,
519	        dry_run: false,
520	    };
521	    crate::squash_push::squash_push(ctx, &sp)?;
522	    Ok(partner)
523	}
524	
525	/// The work half: restamp the unpublished work commit when its
526	/// trailer does not name the partner, then set and push the bookmark.
527	fn work_half(
528	    ctx: &mut Context,
529	    pair: &Pair,
530	    work: &WorkCommit,
531	    bookmark: &str,
532	    params: &PushParams,
533	) -> Result<(), Box<dyn std::error::Error>> {
534	    let target = match crate::pair::partner(pair, work)? {
535	        Partner::Committed(partner) => partner,
536	        Partner::Pending(agent_at) | Partner::Changed { agent_at, .. } => agent_at,
537	    };
538	    let restamp = work.stamped != target;
539	    let dry = if params.dry_run { "[dry-run] " } else { "" };
540	    if restamp {
541	        if is_published(&pair.work, "@-")? {
542	            return Err(format!(
543	                "push: the work @- is published and names {}, not the partner {target}, so it \
544	                 cannot be restamped",
545	                work.stamped
546	            )
547	            .into());
548	        }
549	        warn!(
550	            "push work: {dry}publish {} on {bookmark}, restamping its trailer to name the partner {target}",
551	            work.chid
552	        );
553	    } else {
554	        info!("push work: {dry}publish {} on {bookmark}", work.chid);
555	    }
556	    let work_arg = pair.work.to_string_lossy();
557	    if params.dry_run {
558	        info!("push work: [dry-run] would run jj bookmark set {bookmark} -r @- -R {work_arg}");
559	        info!("push work: [dry-run] would run jj git push --bookmark {bookmark} -R {work_arg}");
560	        return Ok(());
561	    }
562	    let snapshot = Snapshot::take(&pair.work)?;
563	    let local = (|| -> Result<(), Box<dyn std::error::Error>> {
564	        if restamp {
565	            let desc = jj::desc_of(&pair.work, "@-")?;
566	            let text = without_trailers(&desc);
567	            let url_form = crate::desc_helpers::extract_ochid_from_desc(&desc)
568	                .is_some_and(|o| crate::desc_helpers::is_url_form(&o));
569	            let ochid = crate::desc_helpers::ochid_value_in_form(url_form, &pair.agent, &target)?;
570	            let ocid = crate::desc_helpers::extract_ocid_from_desc(&desc);
571	            info!("push work: restamp @- to name {target}");
572	            ctx.session(&pair.work)?.describe(
573	                "@-",
574	                &crate::desc_helpers::with_trailers(&text, &ochid, ocid.as_deref()),
575	            )?;
576	        }
577	        info!("push work: bookmark set {bookmark} -r @- -R {work_arg}");
578	        ctx.session(&pair.work)?.bookmark_set(bookmark, "@-")?;
579	        Ok(())
580	    })();
581	    if let Err(e) = local {
582	        snapshot.restore("push work", e.as_ref());
583	        return Err(e);
584	    }
585	    step_gate(params, "the work bookmark", "the work push")?;
586	    crate::common::verify_tracking(&pair.work, bookmark)?;
587	    info!("push work: git push --bookmark {bookmark} -R {work_arg}");
588	    ctx.session(&pair.work)?.git_push_bookmark(bookmark)?;
589	    Ok(())
590	}
