592	/// A description without its `ochid:` and `ocid:` lines, trimmed, the
593	/// text a partner commit shares.
594	fn without_trailers(desc: &str) -> String {
595	    crate::desc_helpers::without_trailer_lines(desc)
596	        .collect::<Vec<_>>()
597	        .join("\n")
598	        .trim_end()
599	        .to_string()
600	}
