        let fx = Fixture::new("pair-url");
        let pair = resolve_pair(Some(&fx.work)).expect("pair");
        let agent_at = chid(&fx.bot, "@");
        let desc = format!("feat: x\n\nochid: https://example.com/o/r.agent-session#{agent_at}\n");
