/// The profile whose non-empty `suffix` a binary's file stem ends with,
/// so a `-dev` build names the profile that made it. `None` with no
/// match, and with several, which leave the binary's name saying nothing.
pub fn profile_of_binary(root: &Path, stem: &str, label: &str) -> Result<Option<String>, String> {
    let cfg = load_config(root, label)?;
    let mut found = defined_profiles(&cfg.map).into_iter().filter(|name| {
        crate::toml_simple::toml_get(&cfg.map, &format!("profile.{name}.suffix"))
            .is_some_and(|suffix| !suffix.is_empty() && stem.ends_with(suffix.as_str()))
    });
    Ok(match (found.next(), found.next()) {
        (Some(name), None) => Some(name),
        _ => None,
    })
}

